use vstd::prelude::*;

verus! {
    fn concat(a: &[i32], b: &[i32]) -> Vec<i32>
        ensures
            // length of result equals sum of input lengths
            ret.len() == a.len() + b.len(),
            // first part of result matches a
            forall |i: usize| i < a.len() ==> ret[i] == a[i],
            // second part of result matches b
            forall |j: usize| j < b.len() ==> ret[a.len() + j] == b[j],
            // the sequence view is concatenation of a and b sequences
            ret.seq() == a.seq().concat(b.seq()),
    {
        let mut result: Vec<i32> = Vec::with_capacity(a.len() + b.len());

        // Push all elements of a
        let mut i = 0;
        while i < a.len()
            invariant
                i <= a.len(),
                result.len() == i,
                result.seq() == a.seq().slice(0, i),
            decreases a.len() - i,
        {
            result.push(a[i]);
            i += 1;
        }

        // Push all elements of b
        let mut j = 0;
        while j < b.len()
            invariant
                j <= b.len(),
                result.len() == a.len() + j,
                // The combined sequence is a + b[..j]
                result.seq() == a.seq().concat(b.seq().slice(0, j)),
            decreases b.len() - j,
        {
            result.push(b[j]);
            j += 1;
        }

        result
    }
}

